import { z } from "zod";

import type { Me } from "@/lib/api/types";
import { reportError } from "@/lib/monitoring";

/**
 * Runtime checks for API responses. The TypeScript types describe what we
 * expect; these confirm it at the boundary. They are lenient on purpose: an
 * unexpected shape is reported (so drift is noticed) but the raw value is still
 * returned, so a small backend change degrades gracefully instead of blanking
 * the UI. Swap `schema.d.ts` generated by `npm run gen:api` in when the OpenAPI
 * document is available, and tighten these.
 */
const status = z.enum(["open", "pending", "resolved"]);
const priority = z.enum(["urgent", "high", "medium", "low"]);
const role = z.enum(["light_agent", "agent", "supervisor", "admin"]);

export const meSchema = z.looseObject({
  id: z.string(),
  name: z.string(),
  email: z.string(),
  role,
});

export const ticketSummarySchema = z.looseObject({
  id: z.string(),
  label: z.string(),
  subject: z.string(),
  status,
  priority,
  updated_at: z.string(),
});

export const notificationSchema = z.looseObject({
  id: z.string(),
  text: z.string(),
  read: z.boolean(),
});

/** Parse `data`; report a mismatch but never throw. */
export function validate<T>(schema: z.ZodType<T>, data: unknown, label: string): T {
  const r = schema.safeParse(data);
  if (r.success) return r.data;
  reportError(new Error(`Unexpected API response shape: ${label}`), {
    issues: r.error.issues.slice(0, 5).map((i) => `${i.path.join(".")}: ${i.message}`),
  });
  return data as T;
}

export function validateList<T>(schema: z.ZodType, items: T[], label: string): T[] {
  // Check the first item only: cheap, and shape drift shows on every row anyway.
  const first = items[0];
  if (first !== undefined) validate(schema, first, label);
  return items;
}

/**
 * `/me` may carry `workspace` and `status` as objects ({ name, slug } / { status })
 * or as plain strings, and the id as `id` or `member_id`. Flatten to our `Me`.
 */
export function normalizeMe(input: Record<string, unknown>): Me {
  // The API answers { member, workspace }; older shapes were flat.
  const member = input.member as Record<string, unknown> | undefined;
  const raw: Record<string, unknown> = member ? { ...input, ...member } : input;
  const ws = raw.workspace as { name?: string; slug?: string } | string | undefined;
  const st = raw.status as { status?: string; value?: string } | string | null | undefined;
  const me = {
    ...raw,
    id: (raw.id ?? raw.member_id) as string,
    workspace_name:
      (raw.workspace_name as string | undefined) ??
      (typeof ws === "object" ? (ws?.name ?? ws?.slug) : ws),
    workspace: typeof ws === "object" ? ws?.slug : ws,
    status: (typeof st === "object" && st ? (st.status ?? st.value) : st) as Me["status"],
  } as Me;
  return validate(meSchema, me, "GET /me") as Me;
}
